          "greek": "Τον ακολουθούσαν δύο βαστάζοι που βιαστικοί ερχόνταν κατόπι του, φέρνοντας στο κεφάλι μεγάλα στρογγυλά κοφίνια παρόμοια σε δίσκους πλεχτούς, γιομάτα ψάρια, βαστώντας στα δόντια το καπέλο τους και κρατώντας σε ισορροπία το φόρτωμά τους με τα δυο τους χέρια.",
          "translation": "Il était suivi de deux porteurs qui s'empressaient de le suivre, portant sur la tête de gros coffres ronds semblables à des plateaux tressés, des poissons iomata, posant leur chapeau sur leurs dents et balançant leur chargement à deux mains."
