          "translation": "Et d'un geste il se montra à elle, comme s'il voulait lui dire que s'ils étaient là à cette heure, pieds nus, avec sa culotte déboutonnée jusqu'aux genoux, sans veste, avec ses manches déboutonnées, il ne le devait qu'à elle seule."
