          "translation": "Et quelque chose la poussa à se jeter sur eux, à leur arracher les yeux avec son doigt, à les arracher avec ses ongles et avec sa bouche, et elle aurait voulu maintenant avoir deux mains, deux bouches, être elle-même deux personnes, pour pouvoir les saisir tous les deux en même temps et les maltraiter comme ils le méritaient : le barba douloureux et l'homme déshonorant qui avait ruiné sa fille."
